def get_embedded_logo(size):
    try:
        data = base64.b64decode(LOGO_B64)
        img = Image.open(io.BytesIO(data)).convert("RGBA")
        img = img.resize((size, size), Image.LANCZOS)
        return img
    except Exception as e:
        print(f"Logo decode failed: {e}")
        img = Image.new("RGBA", (size, size), (0,0,0,0))
        draw = ImageDraw.Draw(img)
        draw.ellipse((0,0,size,size), fill=BRAND["YELLOW"])
        return img

def load_font(size, bold=False):
    try:
        return ImageFont.truetype("DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf", size)
    except:
        return ImageFont.load_default()

def safe_paste(base_img, logo, pos):
    try:
        if logo.mode == 'RGBA':
            base_img.paste(logo, pos, logo)
        else:
            base_img.paste(logo, pos)
    except:
        try:
            base_img.paste(logo, pos)
        except:
            pass

def add_glow(base_img, center, radius, color=BRAND["YELLOW"]):
    try:
        draw = ImageDraw.Draw(base_img, "RGBA")
        for r in range(radius, radius-60, -10):
            alpha = int(255 * (1 - (radius - r)/60) * 0.14)
            c = (color[0], color[1], color[2], alpha)
            draw.ellipse((center[0]-r, center[1]-r, center[0]+r, center[1]+r), fill=c)
    except:
        pass

