def generate_question_card(q_idx, total, question, opts, selected_idx=None):
    try:
        W,H = 1080,1350
        img = Image.new("RGB", (W,H), BRAND["NAVY"])
        draw = ImageDraw.Draw(img)
        draw.rectangle((0,0,W,100), fill=BRAND["YELLOW"])
        draw.text((25,50), "VIDYASHALA • PREMIUM", fill=BRAND["NAVY"], font=load_font(24, True), anchor="lm")
        draw.text((W-25,50), f"QUESTION {q_idx+1}/{total}", fill=BRAND["NAVY"], font=load_font(24, True), anchor="rm")
        cx,cy = W//2, 240
        add_glow(img, (cx,cy), 110)
        try:
            logo = get_embedded_logo(100)
            safe_paste(img, logo, (cx-50, cy-50))
        except:
            draw.ellipse((cx-40, cy-40, cx+40, cy+40), fill=BRAND["YELLOW"])
        def wrap_text(text, font, max_width):
            words = text.split()
            lines, cur = [], ""
            for w in words:
                test = cur + " " + w if cur else w
                if draw.textlength(test, font=font) <= max_width:
                    cur = test
                else:
                    lines.append(cur)
                    cur = w
            if cur: lines.append(cur)
            return lines
        f_q = load_font(44, True)
        lines = wrap_text(question, f_q, W-100)
        y = 380
        for line in lines[:6]:
            draw.text((W//2, y), line, fill=BRAND["WHITE"], font=f_q, anchor="mm")
            y+=58
        if selected_idx is not None and selected_idx >=0:
            draw.text((W//2, y+30), f"Selected: {chr(65+selected_idx)}", fill=BRAND["YELLOW"], font=load_font(24, True), anchor="mm")
        draw.text((W//2, H-120), "Answer using buttons below • Timer in caption ⏱", fill=BRAND["GRAY"], font=load_font(20, False), anchor="mm")
        buf = io.BytesIO(); img.save(buf, format="PNG"); buf.seek(0); return buf
    except Exception as e:
        print(f"Q card fail: {e}")
        img = Image.new("RGB", (1080,1080), BRAND["NAVY"])
        draw = ImageDraw.Draw(img)
        draw.text((540,540), question[:80], fill=BRAND["WHITE"], font=load_font(30, True), anchor="mm")
        buf = io.BytesIO(); img.save(buf, format="PNG"); buf.seek(0); return buf

