        color = BRAND["RED"] if correctness in ["incorrect","left"] else BRAND["GREEN"]
        draw.rectangle((0,0,W,100), fill=color)
        status = "❌ WRONG" if correctness=="incorrect" else "⏭ LEFT" if correctness=="left" else "✅ CORRECT"
        draw.text((30,50), f"{status} • Q{q_idx+1} • {q_item.get('chapter','')}", fill=BRAND["WHITE"], font=load_font(24, True), anchor="lm")
