            is_skipped = user_ans is None or user_ans==-1
            if is_correct:
                card_bg = (22, 55, 95)
                accent = BRAND["GREEN"]
                icon = "✅"
                status = "CORRECT"
            elif is_skipped:
                card_bg = (35, 45, 75)
                accent = BRAND["GRAY"]
                icon = "⏭"
                status = "SKIPPED"
