def live_updater(uid, total):
    while active_timers.get(uid):
        try:
            cur = sessions[uid]['cur']
            elapsed = time.time() - sessions[uid]['start']
            chat_id, msg_id = timer_msg.get(uid,(None,None))
            if not chat_id:
                break
            quiz = get_quiz()
            q = quiz[cur]
            selected = sessions[uid]['answers'][cur]
            from telebot.types import InlineKeyboardMarkup, InlineKeyboardButton
            markup = get_question_markup(cur, total, len(q['opts']), selected)
            bot.edit_message_caption(caption=get_q_caption(cur, elapsed, total), chat_id=chat_id, message_id=msg_id, reply_markup=markup)
        except:
            pass
        time.sleep(0.8)

def get_question_markup(q_idx, total, num_opts, selected_idx):
    from telebot.types import InlineKeyboardMarkup, InlineKeyboardButton
    markup = InlineKeyboardMarkup(row_width=2)
    buttons = []
    for i in range(num_opts):
        label = f"{'✅ ' if selected_idx==i else ''}{chr(65+i)}"
        buttons.append(InlineKeyboardButton(label, callback_data=f"ans_{q_idx}_{i}"))
    for i in range(0, len(buttons), 2):
        if i+1 < len(buttons):
            markup.row(buttons[i], buttons[i+1])
        else:
            markup.row(buttons[i])
    nav_row = []
    if q_idx > 0:
        nav_row.append(InlineKeyboardButton("⬅️ Back", callback_data=f"back_{q_idx}"))
    if q_idx < total-1:
        nav_row.append(InlineKeyboardButton("Next ➡️", callback_data=f"next_{q_idx}"))
    if nav_row:
        markup.row(*nav_row)
    markup.row(InlineKeyboardButton("✅ Submit Test", callback_data="submit_test"))
    return markup

